public class EscapeSequencePrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n").replace("\t", "\\t") + "\"";
    }

    static String captureQuote(String speaker, String words) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            EscapeSequencePrinter.printQuote(speaker, words);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    static String capturePath(String folder, String file) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            EscapeSequencePrinter.printWindowsPath(folder, file);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("printQuote(\"ada\", \"hello there\")",
                "ada said:\n\t\"hello there\"\n", captureQuote("ada", "hello there"));
        check("printQuote with an empty quote",
                "bo said:\n\t\"\"\n", captureQuote("bo", ""));
        check("printQuote produces two lines", 2, captureQuote("ada", "hi").split("\n", -1).length - 1);
        check("second line starts with a tab", true, captureQuote("ada", "hi").contains("\n\t\""));
        check("printWindowsPath(\"logs\", \"app.txt\")",
                "C:\\logs\\app.txt\n", capturePath("logs", "app.txt"));
        check("printWindowsPath(\"tmp\", \"a.b\")",
                "C:\\tmp\\a.b\n", capturePath("tmp", "a.b"));
        check("path line has exactly two backslashes", 2,
                capturePath("logs", "app.txt").length() - capturePath("logs", "app.txt").replace("\\", "").length());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

