public class EscapeSequencePrinter {

    public static void printQuote(String speaker, String quote) {
        System.out.println(speaker + " said:");
        System.out.println("\t\"" + quote + "\"");
    }

    public static void printWindowsPath(String folder, String file) {
        System.out.println("C:\\" + folder + "\\" + file);
    }
}
